async function generateRepair(){
  const session=repairSession();if(!session)return false;
  const {task:t,result:r,draft:d,shot:s}=session,context={...repairContext},jobEpoch=t.jobEpoch||0;if(d.generating||d.merging)return false;
  const count=Number(d.generateCount||1);if(!Number.isInteger(count)||count<1||count>4)return toast('请选择1至4个版本');const prompt=d.prompts[s.uid]??s.prompt;if(!prompt.trim())return toast('请填写提示词');
  const baseShot=r.versions.find(v=>v.name===d.base)?.shots.find(x=>x.uid===s.uid);if(!baseShot)return toast('未找到原始分镜版本');
  const roles=['妈妈','主播','男孩','爸爸','女孩'],rolePairs=baseShot.refs.map((id,i)=>({id,role:state.assets.find(a=>a.id===id)?.role,ref:s.refs[i]})).filter(x=>roles.includes(x.role));
  const targets=d.scope==='related'?[s,...d.shots.filter(x=>x.uid!==s.uid&&x.method!=='keep'&&x.refs.some(id=>rolePairs.some(pair=>pair.id===id)))]:[s];
  const roleOverrides={};for(const pair of rolePairs){const line=prompt.split('\n').find(line=>line.startsWith('<'+pair.role+'>')&&/@图片\d+/.test(line));if(line)roleOverrides[pair.role]=line}
  const snapshot=targets.map(x=>{
    const refs=x.uid===s.uid?[...s.refs]:x.refs.map(id=>rolePairs.find(pair=>pair.id===id)?.ref||id);
    const ownPrompt=x.uid===s.uid?prompt:(d.prompts[x.uid]??x.prompt);
    return {...cloneWorkflow(x),refs,prompt:syncRepairReferencePrompt(ownPrompt,refs,x.uid===s.uid?baseShot.refs:x.refs,roleOverrides),thumb:refs.find(id=>roles.includes(state.assets.find(a=>a.id===id)?.role))||x.thumb,versionId:workflowId(),accepted:false,requestFingerprint:repairFingerprint(x,d)};
  });
  d.generating=true;delete d.error;save();drawRepair();
  try{
    await new Promise(resolve=>setTimeout(resolve,650));
    if(!state.tasks.includes(t)||(t.jobEpoch||0)!==jobEpoch||r.repairDraft!==d)return false;
    if(d.simulateFailure){d.simulateFailure=false;throw Error('替换版生成失败')}
    snapshot.forEach(x=>{const list=repairCandidates(d,x.uid);for(let i=0;i<count;i++){const candidate={...cloneWorkflow(x),versionId:workflowId(),created:Date.now(),accepted:false};list.push(candidate);if(!d.updates[x.uid]?.accepted)d.updates[x.uid]=candidate}});return true;
  }catch(error){if(r.repairDraft===d)d.error=error.message;return false}
  finally{
    d.generating=false;if(state.tasks.includes(t)&&(t.jobEpoch||0)===jobEpoch&&r.repairDraft===d){save();if(repairUIVisible(context)){drawRepair();toast(d.error?'替换版生成失败，可重试':'替换结果已生成，选用后重新组合')}}
  }
}
async function mergeRepair(){
  const session=repairSession();if(!session)return false;
  const {task:t,result:r,draft:d}=session,context={...repairContext},jobEpoch=t.jobEpoch||0;if(d.generating||d.merging)return false;
  const updates=Object.values(d.updates).filter(x=>x.accepted);if(!updates.length)return false;
  const base=r.versions.find(v=>v.name===d.base);if(!base?.shots?.length)return toast('原成片版本不存在，请重新打开修改');
  const shots=cloneWorkflow(base.shots.map(s=>d.updates[s.uid]?.accepted?d.updates[s.uid]:s));d.merging=true;save();drawRepair();
  try{
    await new Promise(resolve=>setTimeout(resolve,300));
    if(!state.tasks.includes(t)||(t.jobEpoch||0)!==jobEpoch||r.repairDraft!==d)return false;
    if(r.current!==d.base){d.error='当前成片版本已切换，请基于最新版本重新修改';return false}
    const name='v'+(r.versions.length+1);r.versions.push({name,status:'待预览',created:Date.now(),shots});r.current=name;r.status='待预览';delete r.repairDraft;save();
    if(sameRepairContext(context)&&$('#dialog')?.open){$('#dialog').close();clearRepairPlayback()}
    renderTaskIfActive(t);toast('已重新合成 '+name+'，旧版保留在历史中');return true;
  }catch(error){if(r.repairDraft===d)d.error=error.message;return false}
  finally{d.merging=false;if(state.tasks.includes(t)&&(t.jobEpoch||0)===jobEpoch&&r.repairDraft===d){save();if(repairUIVisible(context))drawRepair()}}
}
document.addEventListener('input',e=>{const d=e.target.dataset,t=task();if(d.spField==='newCount'){t.newCount=+e.target.value;t.batchPlans=[];save()}if(d.spField==='clothing'){const p=t.batchPlans.find(x=>x.id===d.id);if(p&&!p.running&&!t.batchRunning){p.clothing=e.target.value;p.confirmed=false;save()}}if(d.spField==='repairPrompt'){const session=repairSession();if(session&&!session.draft.generating&&!session.draft.merging){session.draft.prompts[session.shot.uid]=e.target.value;repairCandidates(session.draft,session.shot.uid);delete session.draft.updates[session.shot.uid];save()}}});
document.addEventListener('change',e=>{const d=e.target.dataset,t=task();if(d.spField==='label'){setVideoLabel(t,d.id,e.target.value)}if(d.spField==='completeLabel'){const r=t.results.find(r=>r.id===d.id);r.status=e.target.value;r.versions.find(v=>v.name===r.current).status=r.status;save();render()}if(d.spField==='repairRef'){const session=repairSession();if(session&&!session.draft.generating&&!session.draft.merging){const {draft,shot:s}=session,oldRefs=[...s.refs];s.refs[+d.slot]=e.target.value;draft.prompts[s.uid]=syncRepairReferencePrompt(draft.prompts[s.uid]??s.prompt,s.refs,oldRefs);repairCandidates(draft,s.uid);delete draft.updates[s.uid];save();drawRepair()}}if(d.spField==='repairCount'){const session=repairSession();if(session&&!session.draft.generating&&!session.draft.merging){session.draft.generateCount=Number(e.target.value);save()}}if(d.spField==='repairScope'){const session=repairSession();if(session&&!session.draft.generating&&!session.draft.merging){session.draft.scope=e.target.value;save()}}if(d.spField==='newCount')render()});
document.addEventListener('click',async e=>{const b=e.target.closest('[data-sp]');if(!b||b.disabled)return;const d=b.dataset,t=workflowState(task());switch(d.sp){case 'expandPrompt':t.shots.find(s=>s.uid===d.uid).promptExpanded=!t.shots.find(s=>s.uid===d.uid).promptExpanded;save();render();break;case 'discarded':t.shots.find(s=>s.uid===d.uid).showDiscarded=!t.shots.find(s=>s.uid===d.uid).showDiscarded;render();break;case 'locate':$('#shot-'+t.shots.find(s=>s.uid===d.uid).id).scrollIntoView({block:'start',behavior:'instant'});break;case 'versionPreview':{const v=t.clipVersions.find(v=>v.id===d.id),s=t.shots.find(s=>s.uid===v?.shotUid);if(s)s.previewMode='selected';setVideoLabel(t,d.id,'已选用');break}case 'samplePreview':{const sample=t.samples.find(s=>s.id===d.id);openSimulation('完整样片预览',sample.shots);break}case 'sourcePreview':openSimulation('原片片段 · 演示示意',[chosenShots(t).find(x=>x.uid===d.uid)]);break;case 'completePreview':{const r=t.results.find(r=>r.id===d.id);if(r.status==='待预览'){r.status='待选用';r.versions.find(v=>v.name===r.current).status=r.status;save();render()}repairResult(t,d.id);break}case 'confirmBatch':if(t.batchPlans.some(p=>p.changes.some(c=>!c.text.trim())))return toast('请补充空白修改项');t.batchPlans.forEach(p=>p.confirmed=true);runWorkflowBatch();break;case 'regeneratePlan':{const p=t.batchPlans.find(p=>p.id===d.id);if(t.batchRunning)return;const existing=t.batchPlans;t.newCount=existing.length;makeWorkflowPlans(t);const replacement=t.batchPlans[(existing.indexOf(p)+1)%t.batchPlans.length];replacement.id=p.id;replacement.changes.forEach(c=>c.text+=' 换成明亮窗边场景。');t.batchPlans=existing.map(x=>x.id===p.id?replacement:x);save();render();break}case 'retryBatch':{const p=t.batchPlans.find(p=>p.id===d.id);if(!p||t.batchRunning||p.running)return;p.confirmed=true;await processBatchPlan(t,p,t.batchPlans.indexOf(p));save();render();break}case 'repair':repairResult(t,d.id);break;case 'repairShot':if(repairSession()){repairContext.uid=d.uid;drawRepair()}break;case 'repairGenerate':generateRepair();break;case 'repairUse':{const session=repairSession(),v=session&&repairCandidates(session.draft,session.shot.uid).find(x=>x.versionId===d.version);if(v&&!session.draft.generating&&!session.draft.merging){repairCandidates(session.draft,session.shot.uid).forEach(x=>x.accepted=false);v.accepted=true;session.draft.updates[session.shot.uid]=v;save();drawRepair()}break}case 'repairEnableEdit':{const session=repairSession();if(session&&!session.draft.generating&&!session.draft.merging){const s=session.shot;s.method='edit';s.prompt='编辑@视频1：保留原脚本、时长和字幕，仅修改明确指定的对象。';save();drawRepair()}break}case 'repairMerge':mergeRepair();break;case 'repairPlay':repairPlaying=!repairPlaying;break;case 'repairNewPreview':{const session=repairSession();if(session)openSimulation('替换分镜预览',[repairCandidates(session.draft,session.shot.uid).find(x=>x.versionId===d.version)||session.draft.updates[session.shot.uid]],true);break}case 'completeHistory':{const r=t.results.find(r=>r.id===d.id);modal(esc(r.name)+' · 历史版本',r.versions.map(v=>`<div class="history-item row between"><span>${v.name} · ${v.status}</span><button data-sp="historyPreview" data-id="${r.id}" data-name="${v.name}">预览</button><button data-sp="restoreComplete" data-id="${r.id}" data-name="${v.name}">恢复此版</button></div>`).join(''));break}case 'historyPreview':{const r=t.results.find(r=>r.id===d.id);openSimulation(r.name+' '+d.name,r.versions.find(v=>v.name===d.name).shots);break}case 'restoreComplete':{const r=t.results.find(r=>r.id===d.id);r.current=d.name;r.status=r.versions.find(v=>v.name===d.name).status;delete r.repairDraft;save();$('#dialog').close();render();break}}});
/* Animated canvas stream: real browser playback, explicitly simulated content. */
const gameCropCache=new WeakMap();
function gameContentBounds(img){if(gameCropCache.has(img))return gameCropCache.get(img);const c=document.createElement('canvas');c.width=img.naturalWidth;c.height=img.naturalHeight;const ctx=c.getContext('2d');ctx.drawImage(img,0,0);const pixels=ctx.getImageData(0,0,c.width,c.height).data;const nonBlack=x=>[.1,.5,.8].some(r=>{const i=(Math.floor(c.height*r)*c.width+x)*4;return pixels[i]+pixels[i+1]+pixels[i+2]>45});let left=0,right=c.width-1;while(left<right&&!nonBlack(left))left++;while(right>left&&!nonBlack(right))right--;const bounds={left,width:right-left+1};gameCropCache.set(img,bounds);return bounds}
const imageCache=new Map();let activeHover=null,repairPlaying=false,repairFrame=0;
function simulationFrame(canvas,shot,elapsed,title='分镜预览'){const ctx=canvas.getContext('2d'),w=canvas.width,h=canvas.height,a=shotCoverAsset(shot);ctx.fillStyle='#202029';ctx.fillRect(0,0,w,h);if(a?.url){let img=imageCache.get(a.url);if(!img){img=new Image();img.src=a.url;imageCache.set(a.url,img)}if(img.complete&&img.naturalWidth){const cols=a.gridColumns||4,rows=a.gridRows||3,sw=typeof a.tile==='number'?img.naturalWidth/cols:img.naturalWidth,sh=typeof a.tile==='number'?img.naturalHeight/rows:img.naturalHeight,sx=typeof a.tile==='number'?(a.tile%cols)*sw:0,sy=typeof a.tile==='number'?Math.floor(a.tile/cols)*sh:0;const scale=Math.max(w/sw,h/sh)*(1+.015*(1+Math.sin(elapsed/900)));if(a.role==='原片记录'){const bounds=gameContentBounds(img),gameX=bounds.left,gameW=bounds.width;const backScale=Math.max(w/gameW,h/img.naturalHeight)*1.04;ctx.save();ctx.filter='blur(10px) brightness(.75)';ctx.drawImage(img,gameX,0,gameW,img.naturalHeight,(w-gameW*backScale)/2,(h-img.naturalHeight*backScale)/2,gameW*backScale,img.naturalHeight*backScale);ctx.restore();const fit=Math.min(w/gameW,h/img.naturalHeight);ctx.drawImage(img,gameX,0,gameW,img.naturalHeight,(w-gameW*fit)/2,(h-img.naturalHeight*fit)/2,gameW*fit,img.naturalHeight*fit)}else{ctx.drawImage(img,sx,sy,sw,sh,(w-sw*scale)/2,(h-sh*scale)/2,sw*scale,sh*scale)}}}ctx.fillStyle='#15203988';ctx.fillRect(0,h-90,w,90);ctx.fillStyle='white';ctx.font='14px sans-serif';ctx.fillText(title,12,24);const words=(shot?.speech||shot?.description||'视频交互演示').match(/.{1,16}/g)||[];const text=words[Math.floor(elapsed/1500)%Math.max(1,words.length)]||'';ctx.fillText(text,12,h-65);ctx.font='11px sans-serif';ctx.fillStyle='#7499ff';ctx.fillRect(12,h-15,(w-24)*(elapsed%6000)/6000,3)}
function startSimulation(video,shots){shots=shots?.length?shots:[{description:'历史成片演示',thumb:'family-image-2'}];const canvas=document.createElement('canvas');canvas.width=270;canvas.height=480;const stream=canvas.captureStream?.(24);if(stream){video.srcObject=stream;video.muted=true;video.play().catch(()=>{})}let alive=true,frame=0,start=performance.now();function tick(){if(!alive||!video.isConnected){stop();return}const elapsed=performance.now()-start,total=shots.reduce((n,s)=>n+(s.duration||6)*1000,0),at=elapsed%total;let accumulated=0,index=0;for(let i=0;i<shots.length;i++){accumulated+=(shots[i].duration||6)*1000;if(at<accumulated){index=i;break}}simulationFrame(canvas,shots[index],at,`分镜 ${shots[index]?.number||index+1}`);frame=requestAnimationFrame(tick)}function stop(){alive=false;cancelAnimationFrame(frame);stream?.getTracks().forEach(t=>t.stop());video.pause();video.srcObject=null}stop.seek=n=>{start=performance.now()-shots.slice(0,n).reduce((total,s)=>total+(s.duration||6)*1000,0)};tick();return stop}
let viewerPlayback=null;
function openSimulation(title,shots,returnRepair=false){shots=shots?.filter(Boolean)||[];viewerPlayback?.();modal(esc(title),`<div class="sp-viewer"><div class="sp-screen"><video class="sp-modal-video" id="sp-video" autoplay muted playsinline controls></video><p class="small muted">9:16 · 视频预览</p></div><div class="sp-chapters"><h3>${shots.length>1?'完整成片 · '+shots.length+' 个分镜':'分镜预览'}</h3><p class="small muted">点击分镜可跳转预览</p>${shots.map((s,i)=>`<button class="sp-chapter" data-bp-action="seekPreview" data-number="${i}"><b>分镜 ${s.number||i+1} <span class="badge">${s.method==='keep'?'原片':'生成版本'}</span></b><p>${esc(s.description||'')}</p>${s.method==='keep'?`<small class="muted">${esc(shortRange(s))}</small>`:''}</button>`).join('')}<p class="small muted">当前为演示画面，真实生成与编码尚未接入。</p></div></div>`,returnRepair?'<button data-sp="returnRepair">返回修改</button>':'');viewerPlayback=startSimulation($('#sp-video'),shots)}

