function stopHover(){activeHover?.stop?.();activeHover?.box.remove();activeHover=null}
function positionMediaPreview(box,button,width,height){
  const rect=button.getBoundingClientRect(),gap=10,limit=Math.max(130,Math.min(width,innerWidth-16));
  let left=rect.right+gap;
  if(left+limit>innerWidth-8)left=rect.left-limit-gap;
  if(left<8)left=Math.max(8,Math.min(innerWidth-limit-8,rect.left));
  box.style.width=limit+'px';box.style.height=Math.min(height,innerHeight-16)+'px';
  box.style.left=left+'px';box.style.top=Math.max(8,Math.min(innerHeight-Math.min(height,innerHeight-16)-8,rect.top))+'px';
}
