function showHover(button){
  stopHover();let shots=[{thumb:button.dataset.spHover,description:'分镜预览',speech:''}];const t=task(),id=button.dataset.id;
  if(button.dataset.sp==='completePreview'){const r=t?.results.find(r=>r.id===id);shots=r?.versions.find(v=>v.name===r.current)?.shots||[]}
  else if(button.dataset.sp==='versionPreview'){const v=t?.clipVersions.find(v=>v.id===id);if(!v||['生成中','生成失败'].includes(v.status))return;shots=[v]}
  else if(button.dataset.sp==='sourcePreview')shots=[chosenShots(t).find(s=>s.uid===button.dataset.uid)].filter(Boolean);
  else if(button.dataset.sp==='repairNewPreview'){const session=repairSession();shots=session?[repairCandidates(session.draft,session.shot.uid).find(x=>x.versionId===button.dataset.version)||session.draft.updates[session.shot.uid]].filter(Boolean):[]}
  const box=document.createElement('div');box.className='sp-hover';const video=document.createElement('video');video.autoplay=true;video.muted=true;video.playsInline=true;box.append(video);document.body.append(box);
  positionMediaPreview(box,button,innerWidth<650?160:210,innerWidth<650?285:374);activeHover={box,stop:startSimulation(video,shots),button};
}
function showReferenceHover(button){
  stopHover();const a=state.assets.find(a=>a.id===button.dataset.i);if(!a?.url)return;
  const box=document.createElement('div');box.className='sp-image-hover';box.innerHTML=assetVisual(a,'sp-reference-image');document.body.append(box);
  positionMediaPreview(box,button,230,260);activeHover={box,button};
}
document.addEventListener('pointerover',e=>{
  const image=e.target.closest('[data-sp-image-hover]'),main=e.target.closest('[data-sp-main]'),b=e.target.closest('[data-sp-hover]');
  if(image&&!image.contains(e.relatedTarget))showReferenceHover(image);
  else if(main&&!main.contains(e.relatedTarget))showMainPlayback(main);
  else if(b&&!b.contains(e.relatedTarget))showHover(b);
});
document.addEventListener('pointerout',e=>{
  const b=e.target.closest('[data-sp-hover],[data-sp-image-hover]');if(b&&!b.contains(e.relatedTarget))stopHover();
  const main=e.target.closest('[data-sp-main]');if(main&&!main.contains(e.relatedTarget))stopMainPlayback();
});
document.addEventListener('focusin',e=>{const image=e.target.closest('[data-sp-image-hover]'),main=e.target.closest('[data-sp-main]'),b=e.target.closest('[data-sp-hover]');if(image)showReferenceHover(image);else if(main)showMainPlayback(main);else if(b)showHover(b)});
document.addEventListener('focusout',()=>{stopHover();stopMainPlayback()});window.addEventListener('scroll',stopHover,true);window.addEventListener('resize',()=>{stopHover();stopMainPlayback()});
if(typeof MutationObserver!=='undefined')new MutationObserver(()=>{
  if(activeHover&&!activeHover.button.isConnected)stopHover();
  if(mainPlayback&&!mainPlayback.button.isConnected)stopMainPlayback();
}).observe(document.body,{childList:true,subtree:true});
function startRepairCanvas(shots,uid){cancelAnimationFrame(repairFrame);repairPlaying=false;let elapsed=0,previous=performance.now();const start=shots.slice(0,shots.findIndex(s=>s.uid===uid)).reduce((n,s)=>n+(s.duration||8),0),total=shots.reduce((n,s)=>n+(s.duration||8),0);elapsed=start*1000;function tick(now){const canvas=$('#repair-player');if(!canvas)return;if(repairPlaying)elapsed=(elapsed+now-previous)%(total*1000);previous=now;let position=0,index=0;for(let i=0;i<shots.length;i++){if(elapsed/1000<position+(shots[i].duration||8)){index=i;break}position+=shots[i].duration||8}simulationFrame(canvas,shots[index],elapsed,`分镜 ${shots[index].number} · ${(elapsed/1000).toFixed(1)}秒`);document.querySelectorAll('[data-sp="repairShot"]').forEach(b=>b.classList.toggle('primary',b.dataset.uid===shots[index].uid));repairFrame=requestAnimationFrame(tick)}repairFrame=requestAnimationFrame(tick)}
const oldSinglePageAssets=assets;
assets=function(){if(assetTab==='raw')return oldSinglePageAssets();const results=state.tasks.flatMap(t=>{workflowState(t);return t.results.map(r=>({...r,taskId:t.id,taskName:t.name}))}).filter(r=>(assetFilter==='全部'?r.status!=='已弃用':r.status===assetFilter)&&`${r.taskName} ${r.name}`.includes(assetQuery));return `<main><h1>资产库</h1><div class="tabs"><button data-action="assetTab" data-tab="finished" class="active">成片</button><button data-action="assetTab" data-tab="raw">原料素材</button></div><div class="row wrap section-title">${['全部',...RESULT_LABELS].map(x=>`<button data-action="filter" data-filter="${x}" class="${assetFilter===x?'primary':''}">${x}</button>`).join('')}</div><div class="sp-completes">${results.map(r=>`<article class="sp-complete">${thumb(r.versions.find(v=>v.name===r.current)?.shots?.[0]||r.templateSnapshot?.shots?.[0]||{thumb:'family-image-2'},`data-sp="assetComplete" data-id="${r.id}"`)}<div><h3>${esc(r.name)} · ${r.current}</h3><p class="small muted">${esc(r.taskName)} · ${r.status}</p><button data-sp="assetReturn" data-id="${r.id}">查看 / 修改此视频</button></div></article>`).join('')||'<p class="muted">暂无匹配成片。</p>'}</div></main>`};
/* Persist the details state without forcing a page change. */
document.addEventListener('click',e=>{const b=e.target.closest('[data-sp="assetReturn"],[data-sp="assetComplete"]');if(!b)return;const t=state.tasks.find(t=>t.results.some(r=>r.id===b.dataset.id));active=t.id;view='work';render();if(b.dataset.sp==='assetReturn')repairResult(t,b.dataset.id);else{const r=t.results.find(r=>r.id===b.dataset.id);openSimulation(r.name,r.versions.find(v=>v.name===r.current).shots)}});
document.addEventListener('toggle',e=>{if(e.target.id==='sp-batch'){task().batchOpen=e.target.open;save()}},true);
