/* Two stages in one task: the template is edited separately from production. */
function newTrialTask(){const t=seedFamilyTask();t.id='trial-'+workflowId();t.name='核桃编程 · 从头体验 '+(state.tasks.filter(t=>t.trial).length+1);t.folder=currentFolder;t.phase='template';t.trial=true;workflowState(t);state.tasks.unshift(t);const folder=state.folders.find(f=>f.id===currentFolder);if(folder)folder.open=true;active=t.id;view='work';save();render();return t}
function ensurePlanDesign(p,index){if(p.design)return p.design;const refs=p.changes.flatMap(c=>c.refs);p.design={mom:{ref:refs.find(id=>state.assets.find(a=>a.id===id)?.role==='妈妈')||'family-image-0',hair:['低马尾','齐耳短发','半扎发','自然披肩发'][index%4],outfit:['米白围裙＋浅灰针织衫','浅绿家居服','浅蓝衬衫＋白色围裙','米色针织衫'][index%4]},host:{ref:refs.find(id=>state.assets.find(a=>a.id===id)?.role==='主播')||'family-image-2',hair:['自然披肩长发','低马尾','齐肩直发','半扎长发'][index%4],outfit:['蓝色针织开衫＋白T','米白衬衫','浅灰针织开衫','淡蓝衬衫'][index%4]},mealScene:['窗边原木厨房，自然光、浅木餐桌','绿植庭院餐厅，白色餐桌、柔和晨光','明亮现代厨房，白瓷砖、木色橱柜','宽敞家庭餐厅，落地窗、原木餐桌'][index%4],hostScene:['绿植客厅，米白沙发、自然光','阳光书房，白色书架、浅木书桌','晚霞天台，远处城市建筑','浅色客厅，落地窗、灰白布艺沙发'][index%4]};return p.design}
function syncPlanDesign(t,p,index){const design=ensurePlanDesign(p,index),template=t.templates.find(x=>x.id===p.templateId);for(const c of p.changes){const s=template.shots.find(x=>x.uid===c.uid),mom=/妈妈/.test(s.description),person=mom?design.mom:design.host,role=mom?'妈妈':'主播';c.refs=s.refs.filter(id=>state.assets.find(a=>a.id===id)?.role!=='场景').map(id=>state.assets.find(a=>a.id===id)?.role===role?person.ref:id);c.prompt=s.prompt.split('\n').filter(line=>!line.startsWith('<')&&!line.startsWith('【本方案')).join('\n')+'\n【本批次覆盖要求】\n'+c.refs.map((id,i)=>{const a=state.assets.find(a=>a.id===id);return a.role===role?`<${role}>的面部身份参考@图片${i+1}（${a.name}），只参考脸部；发型改为${person.hair}，穿${person.outfit}，不要继承参考图服装和背景。`:(SEEDANCE_ROLE_LINES[FAMILY_DEMO_ASSETS.findIndex(a=>a.id===id)]||'@图片{n}约束对应素材外观。').replaceAll('{n}',i+1)}).join('\n')+`\n场景改为：${mom?design.mealScene:design.hostScene}。场景依文字生成，不引用场景图片。未指定修改的动作、脚本、字幕、商品和时长沿用@视频1。`;c.text=`${role}：${state.assets.find(a=>a.id===person.ref).name}；发型${person.hair}；服装${person.outfit}；场景${mom?design.mealScene:design.hostScene}`}p.clothing='';return p}
const makePlansBeforeCompact=makeWorkflowPlans;
makeWorkflowPlans=function(t){const ok=makePlansBeforeCompact(t);if(ok)t.batchPlans.forEach((p,i)=>syncPlanDesign(t,p,i));return ok};
function planFace(p,role,title,index){const person=p.design[role],asset=state.assets.find(a=>a.id===person.ref);return `<div class="bp-person"><button class="sp-face" data-action="assetPreview" data-i="${person.ref}" aria-label="${title}脸部参考">${assetVisual(asset,'mini')}<span class="wf-reference-zoom">${assetVisual(asset,'mini')}</span></button><label><span>${title} · 参考脸</span><select aria-label="方案${index+1}${title}图片" data-bp="ref" data-role="${role}" data-id="${p.id}" ${p.running?'disabled':''}>${state.assets.filter(a=>a.role===(role==='mom'?'妈妈':'主播')).map(a=>`<option value="${a.id}" ${a.id===person.ref?'selected':''}>${esc(a.name)}</option>`).join('')}</select></label></div>`}
function planAppearance(p,role,title,index){return `<div class="bp-appearance"><span>${title}</span><input class="bp-edit" aria-label="方案${index+1}${title}发型" value="${esc(p.design[role].hair)}" data-bp="hair" data-role="${role}" data-id="${p.id}" ${p.running?'disabled':''}><input class="bp-edit" aria-label="方案${index+1}${title}服装" value="${esc(p.design[role].outfit)}" data-bp="outfit" data-role="${role}" data-id="${p.id}" ${p.running?'disabled':''}></div>`}
function compactPlan(p,i){ensurePlanDesign(p,i);return `<div class="bp-row" role="row"><div role="cell"><b>方案 ${String(i+1).padStart(2,'0')}</b><p class="small muted">${p.status==='生成中'?'生成中':p.status==='已生成'?'已生成':p.confirmed?'已确认':'待确认'}</p></div><div role="cell">${planFace(p,'mom','妈妈',i)}${planFace(p,'host','主播',i)}</div><div role="cell">${planAppearance(p,'mom','妈妈',i)}${planAppearance(p,'host','主播',i)}</div><div role="cell"><label class="small"><span class="bp-scene-label">用餐</span><textarea class="bp-edit" rows="2" aria-label="方案${i+1}用餐场景" data-bp="mealScene" data-id="${p.id}" ${p.running?'disabled':''}>${esc(p.design.mealScene)}</textarea></label><label class="small"><span class="bp-scene-label">主播</span><textarea class="bp-edit" rows="2" aria-label="方案${i+1}主播场景" data-bp="hostScene" data-id="${p.id}" ${p.running?'disabled':''}>${esc(p.design.hostScene)}</textarea></label></div><div role="cell"><button class="link small" data-bp-action="redesign" data-id="${p.id}" ${p.running?'disabled':''}>重新搭配</button><button class="link small" data-bp-action="details" data-id="${p.id}">查看引用</button></div></div>`}
batchSection=function(t){const template=t.templates.at(-1);if(!template)return '<section class="panel"><h2>批量生产</h2><p>先确认成片并固定为模板。</p></section>';return `<section class="panel bp-brief"><div class="row between"><h2>批量要求</h2><span class="badge green">基于模板 v${template.number}</span></div><p class="small muted">先确认人物、打扮和场景搭配，再生成完整视频。</p><textarea aria-label="批量模糊需求" data-wf-field="batchBrief" ${t.batchRunning?'disabled':''} placeholder="例如：换不同妈妈和主播，搭配不同衣服、发型和吃饭场景；保留脚本、商品、男孩和原片镜头。">${esc(t.batchBrief||'')}</textarea><div class="row between wrap"><div class="row"><button data-bp-action="fillBatch">填入示例要求</button><label class="small">新增 <input class="wf-count" type="number" min="1" max="12" aria-label="新增视频数量" data-sp-field="newCount" ${t.batchRunning?'disabled':''} value="${t.newCount||4}"> 条</label></div><button class="primary" data-wf="makePlans" ${t.batchRunning?'disabled':''}>生成批量方案</button></div></section>${t.batchPlans.length?`<section class="panel bp-schemes"><div class="row between"><h2>搭配方案 <span class="small muted">${t.batchPlans.length} 条</span></h2><span class="small muted">直接点击文字修改</span></div><p class="small muted">统一保留：原脚本、男孩、商品外观及原片分镜（含其中人物）。图片仅参考脸；场景用文字描述。</p><div class="bp-table" role="table" aria-label="批量搭配方案"><div class="bp-row bp-head" role="row"><span>方案</span><span>人物 / 图片引用</span><span>发型与服装</span><span>新场景</span><span>操作</span></div>${t.batchPlans.map(compactPlan).join('')}</div><div class="row between wrap bp-submit"><span class="small muted">仅生成变化镜头，其他镜头沿用模板</span><button class="primary" data-sp="confirmBatch" ${t.batchRunning||t.batchPlans.every(p=>p.status==='已生成')?'disabled':''}>${t.batchRunning?'批量生成中':'确认方案并生成 '+t.batchPlans.length+' 条视频'}</button></div></section>`:''}${t.batchPlans.filter(p=>p.status==='生成失败').map(p=>`<div class="notice">${esc(p.error)} <button data-sp="retryBatch" data-id="${p.id}">重试失败镜头</button></div>`).join('')}${t.results.some(r=>r.workflowBatch)?`<section class="panel" id="sp-completes"><h2>批量成片 <span class="small muted">直接预览完整视频，有问题再修改分镜</span></h2><div class="sp-completes">${completeCards(t)}</div></section>`:'<div class="bp-empty small muted">确认方案并生成后，完整视频会显示在这里。</div>'}`};
work=function(){const t=workflowState(task()),batch=t.phase==='batch',chosen=chosenShots(t),missing=t.shots.filter(s=>resolveShot(t,s).reason);return `<main class="wf-main" data-workflow-tab="${batch?'批量':'制作'}"><div class="row between"><div><h1>${esc(t.name)}</h1><p class="small muted">${t.trial?'从空白开始体验 · ':''}${t.templates.length?'模板 v'+t.templates.length+' 已固定':'六镜制作示例'} · 自动保存</p></div><button data-bp-action="newTrial">从头体验示例</button></div><nav class="bp-phases" aria-label="任务阶段"><button class="${!batch?'active':''}" data-bp-action="phase" data-phase="template">模板制作</button><button class="${batch?'active':''}" data-bp-action="phase" data-phase="batch" ${!t.templates.length?'disabled title="先确认模板"':''}>批量生产${!t.templates.length?' · 先确认模板':''}</button></nav>${batch?batchSection(t):`${brief(t)}<div class="section-title"><h2>分镜工作区 <span class="muted small">${t.shots.length} 镜</span></h2><div class="row"><button data-action="undoCuts" ${!t.undoCuts?'disabled':''}>撤销调整</button><button data-action="addShot">＋ 新增分镜</button></div></div>${t.shots.map(s=>shotCard(s,t)).join('')}${samePageAssembly(t)}${t.templates.length?'<section class="panel bp-start"><span><b>模板已就绪</b><p class="small muted">进入批量生产，搭配新人物、服装和场景。</p></span><button class="primary" data-bp-action="phase" data-phase="batch">开始批量生产</button></section>':''}<div class="bottom row between"><span class="small">可组装 ${chosen.filter(s=>s.versionId).length}/${t.shots.length} 镜 ${t.parsed&&missing.length?`<button class="link small" data-sp="locate" data-uid="${missing[0].uid}">分镜${missing[0].id+1}：${resolveShot(t,missing[0]).reason}</button>`:''}</span><button class="primary" data-wf="assemble" ${!readyForSample(t)||t.samples.some(s=>s.status==='组装中')?'disabled':''}>${t.samples.some(s=>s.status==='组装中')?'组装中…':'组装成片'}</button></div>`}</main>`};
function updatePlanField(t,p,d,value){if(p.running||t.batchRunning)return false;ensurePlanDesign(p,t.batchPlans.indexOf(p));if(d.role)p.design[d.role][d.bp]=value;else p.design[d.bp]=value;p.confirmed=false;p.status='待确认';delete p.generated;delete p.resultId;syncPlanDesign(t,p,t.batchPlans.indexOf(p));save();return true}
document.addEventListener('input',e=>{const d=e.target.dataset;if(!d.bp||d.bp==='ref')return;const t=task(),p=t.batchPlans.find(p=>p.id===d.id);if(p)updatePlanField(t,p,d,e.target.value)});
document.addEventListener('change',e=>{const d=e.target.dataset;if(!d.bp)return;const t=task(),p=t.batchPlans.find(p=>p.id===d.id);if(p&&updatePlanField(t,p,d,e.target.value))render()});
document.addEventListener('click',e=>{const b=e.target.closest('[data-bp-action]');if(!b||b.disabled)return;const d=b.dataset,t=task();switch(d.bpAction){case 'seekPreview':viewerPlayback?.seek(+d.number);break;case 'newTrial':newTrialTask();window.scrollTo({top:0});toast('已创建空白体验任务，原任务保留');break;case 'phase':if(d.phase==='batch'&&!t.templates.length)return;t.phase=d.phase;save();render();window.scrollTo({top:0});break;case 'fillBatch':if(t.batchRunning)return;t.batchBrief='换不同妈妈和主播，人物约30岁，搭配不同发型、衣服和吃饭场景；原脚本、男孩、礼盒外观和原片镜头保持不变。';t.batchPlans=[];save();render();break;case 'redesign':{if(t.batchRunning)return;const p=t.batchPlans.find(p=>p.id===d.id);p.design=null;ensurePlanDesign(p,((p.variant||t.batchPlans.indexOf(p))+1)%4);p.variant=(p.variant||t.batchPlans.indexOf(p))+1;p.design.mom.ref=p.design.mom.ref==='family-image-0'?'family-image-1':'family-image-0';p.design.host.ref=p.design.host.ref==='family-image-2'?'family-image-3':'family-image-2';p.confirmed=false;p.status='待确认';delete p.generated;syncPlanDesign(t,p,t.batchPlans.indexOf(p));save();render();break}case 'details':{const p=t.batchPlans.find(p=>p.id===d.id);modal('方案 '+(t.batchPlans.indexOf(p)+1)+' · 图片引用与分镜要求',`<p class="small muted">每镜图片编号独立；人物只参考脸，发型与服装按文字修改。场景不引用图片。</p>${p.changes.map(c=>`<details class="history-item"><summary>分镜 ${c.number} · ${esc(c.text)}</summary><div class="row wrap">${c.refs.map((id,i)=>`<span class="ref">${assetVisual(state.assets.find(a=>a.id===id),'mini')}@图片${i+1} = ${esc(state.assets.find(a=>a.id===id).name)}</span>`).join('')}</div><pre class="wf-prompt-text">${esc(c.prompt)}</pre></details>`).join('')}`);break}}});
save();render();
